#include "ati_texture_layout.h"
#include <cassert>
#include <cstdio>
#include <vector>
#ifdef _WIN32
#include <windows.h>
#else
#include <sys/mman.h>
#include <unistd.h>
#endif

// The resource ends immediately before a page that cannot be read or written.
class GuardedBytes {
  void* m_base = nullptr;
  size_t m_mapped = 0;
public:
  uint8_t* data = nullptr;
  explicit GuardedBytes(size_t bytes) {
#ifdef _WIN32
    SYSTEM_INFO info {};
    GetSystemInfo(&info);
    const size_t page = info.dwPageSize;
#else
    const size_t page = static_cast<size_t>(sysconf(_SC_PAGESIZE));
#endif
    const size_t accessible = ((bytes + page - 1) / page) * page;
    m_mapped = accessible + page;
#ifdef _WIN32
    m_base = VirtualAlloc(nullptr, m_mapped, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    assert(m_base);
    DWORD previous = 0;
    assert(VirtualProtect(static_cast<uint8_t*>(m_base) + accessible, page, PAGE_NOACCESS, &previous));
#else
    m_base = mmap(nullptr, m_mapped, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    assert(m_base != MAP_FAILED);
    assert(mprotect(static_cast<uint8_t*>(m_base) + accessible, page, PROT_NONE) == 0);
#endif
    data = static_cast<uint8_t*>(m_base) + accessible - bytes;
  }
  ~GuardedBytes() {
#ifdef _WIN32
    VirtualFree(m_base, 0, MEM_RELEASE);
#else
    munmap(m_base, m_mapped);
#endif
  }
  GuardedBytes(const GuardedBytes&) = delete;
  GuardedBytes& operator=(const GuardedBytes&) = delete;
};

static void testFull(uint32_t width, uint32_t height, uint32_t format) {
  using namespace l4d2_ati;
  const uint32_t blockBytes = format == kAti1 ? 8u : 16u;
  const uint32_t pitch = ((width + 3) / 4) * blockBytes;
  const uint32_t rows = (height + 3) / 4;
  const size_t bytes = static_cast<size_t>(pitch) * rows;
  Layout l;
  Transfer t;
  assert(layout(width, height, format, l));
  assert(l.apiPitch == ((width + 3) & ~3u));
  assert(l.storagePitch == pitch && l.rows == rows && l.bytes == bytes && l.backingBytes >= bytes);
  assert(region(l, 0, 0, static_cast<int32_t>(width), static_cast<int32_t>(height), t));
  assert(t.rowBytes == pitch && t.rows == rows && t.bytes == bytes && t.offset == 0);
  GuardedBytes client(bytes), transport(bytes), server(bytes), returned(bytes);
  for (size_t i = 0; i < bytes; ++i) { client.data[i] = static_cast<uint8_t>((i * 131u + i / 256u) ^ 0x97u); }
  // The same production helper packs the client, writes the backend and returns its bytes.
  assert(copyRows(transport.data, bytes, t.rowBytes, client.data, bytes, l.storagePitch, t));
  assert(copyRows(server.data, bytes, l.storagePitch, transport.data, bytes, t.rowBytes, t));
  assert(copyRows(returned.data, bytes, t.rowBytes, server.data, bytes, l.storagePitch, t));
  assert(std::memcmp(client.data, returned.data, bytes) == 0);
  assert(!copyRows(server.data, bytes - 1, l.storagePitch, transport.data, bytes, t.rowBytes, t));
  assert(!copyRows(server.data, bytes, l.storagePitch, transport.data, bytes - 1, t.rowBytes, t));
  assert(!copyRows(server.data, bytes, l.storagePitch, transport.data, bytes, t.rowBytes - 1, t));
}

static void testPartial(uint32_t format) {
  using namespace l4d2_ati;
  Layout l;
  Transfer t;
  assert(layout(64, 64, format, l));
  // This offset is the actual ATI LockImage API convention, not a block-coordinate offset.
  assert(region(l, 4, 4, 20, 20, t));
  assert(t.offset == 4u * 64u + 4u);
  const uint32_t blockBytes = format == kAti1 ? 8u : 16u;
  assert(t.rows == 4 && t.rowBytes == 4u * blockBytes);
  GuardedBytes client(l.bytes), server(l.bytes), transport(t.bytes);
  std::memset(client.data, 0x93, l.bytes);
  std::memset(server.data, 0x19, l.bytes);
  for (uint32_t row = 0; row < t.rows; ++row) {
    for (uint32_t x = 0; x < t.rowBytes; ++x) {
      client.data[t.offset + static_cast<size_t>(row) * l.storagePitch + x] = static_cast<uint8_t>(row * 41 + x);
    }
  }
  assert(copyRows(transport.data, t.bytes, t.rowBytes, client.data + t.offset, l.bytes - t.offset, l.storagePitch, t));
  assert(copyRows(server.data + t.offset, l.bytes - t.offset, l.storagePitch, transport.data, t.bytes, t.rowBytes, t));
  for (size_t i = 0; i < l.bytes; ++i) {
    bool written = false;
    for (uint32_t row = 0; row < t.rows; ++row) {
      const size_t start = t.offset + static_cast<size_t>(row) * l.storagePitch;
      written |= i >= start && i < start + t.rowBytes;
    }
    assert(server.data[i] == (written ? client.data[i] : 0x19));
  }
  // Shared heap uses real storage pitch on both sides and the same native API offset.
  std::memset(server.data, 0x19, l.bytes);
  assert(copyRows(server.data + t.offset, l.bytes - t.offset, l.storagePitch,
    client.data + t.offset, l.bytes - t.offset, l.storagePitch, t));
  assert(!region(l, -1, 0, 8, 8, t));
  assert(!region(l, 0, 0, 65, 64, t));
  assert(!region(l, 0, 0, 0, 8, t));
  if (format == kAti1) { assert(!region(l, 60, 60, 64, 64, t)); }
}

int main() {
  using namespace l4d2_ati;
  for (const auto format : { kAti1, kAti2 }) {
    for (const uint32_t size : { 1u, 2u, 3u, 4u, 8u, 16u, 64u, 256u, 512u, 1024u, 2048u, 4096u }) {
      testFull(size, size, format);
    }
    testFull(7, 5, format);
    testFull(4, 1, format);
    testFull(1, 4, format);
    testFull(2048, 256, format);
    testPartial(format);
  }
  Layout l;
  assert(layout(1024, 1024, kAti1, l) && l.bytes == 524288 && l.apiPitch == 1024 && l.storagePitch == 2048);
  assert(layout(1024, 1024, kAti2, l) && l.bytes == 1048576 && l.apiPitch == 1024 && l.storagePitch == 4096);
  assert(!layout(0, 1, kAti1, l));
  assert(!layout(16385, 1, kAti1, l));
  assert(!layout(64, 64, 21, l));
  std::puts("PASS: ATI1/ATI2 native API pitch, full mip chains, partial copies, shared storage and guarded upload/readback bounds");
}
